<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requireLogin();if(!Auth::canAccess('tables')){http_response_code(403);exit('Forbidden');}$id=(int)($_GET['id']??0);$pdo=Database::connection();$s=$pdo->prepare('SELECT * FROM restaurant_tables WHERE id=?');$s->execute([$id]);$t=$s->fetch();if(!$t){http_response_code(404);exit('Meja tidak ditemukan.');}$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll() as $r)$settings[$r['setting_key']]=$r['setting_value'];$base=rtrim($settings['base_url']??'','/');if($base===''){$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$dir=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME'])),'/');$base=$scheme.'://'.($_SERVER['HTTP_HOST']??'localhost').$dir;}$url=$base.'/order.php?t='.$t['qr_token'];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR Meja <?=htmlspecialchars($t['table_number'])?></title><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>body{font-family:system-ui;background:#f7efe4;display:grid;place-items:center;min-height:100vh;margin:0;color:#3b2415}.card{background:#fff;padding:32px;border-radius:24px;text-align:center;box-shadow:0 20px 60px #0002;width:min(360px,85vw)}h1{margin:0 0 5px}.muted{color:#7c6249;font-size:13px}.qr{display:flex;justify-content:center;margin:24px}.url{font-size:10px;word-break:break-all}.btn{margin-top:18px;padding:10px 16px;border:0;border-radius:9px;background:#e8672b;color:#fff;font-weight:700}@media print{body{background:#fff}.card{box-shadow:none}.btn{display:none}}</style></head><body><div class="card"><div class="muted">KEDAI BARA · DIGITAL ORDERING</div><h1>Meja <?=htmlspecialchars($t['table_number'])?></h1><p class="muted">Scan untuk melihat menu dan memesan langsung.</p><div class="qr" id="qr"></div><div class="url"><?=htmlspecialchars($url)?></div><button class="btn" onclick="window.print()">Print QR</button></div><script>new QRCode(document.getElementById('qr'),{text:<?=json_encode($url)?>,width:220,height:220});</script></body></html>
